package com.aoo.bcg.wordcard;import java.util.*;final class AhphzRuleSet implements WordCardRuleSet<AhphzRuleSet.Context>{record Context(AhphzRules.Config config,int huXi,boolean canHu,Set<Integer>passedChi,boolean fromOpposite){}public Set<WordCardOperation>allowedOperations(int s,Context c){var x=EnumSet.allOf(WordCardOperation.class);if(c.config.oppositeCannotChi()&&c.fromOpposite)x.remove(WordCardOperation.CHI);if(!c.canHu)x.remove(WordCardOperation.HU);return x;}public boolean canWin(int s,List<Integer>h,int i,Context c){return c.canHu&&AhphzRules.canHu(h,c.huXi);}}
